widget\",\"settings\":{\"style\":\"x_tribal\",\"width\":{\"unit\":\"px\",\"size\":633,\"sizes\":[]},\"width_tablet\":{\"unit\":\"custom\",\"size\":\"\",\"sizes\":[]},\"width_mobile\":{\"unit\":\"custom\",\"size\":\"\",\"sizes\":[]},\"align\":\"center\",\"look\":\"line_text\",\"text\":\"Futurionix and the future of bio-synthetic enhancements\",\"color\":\"#4F169C\",\"pattern_height\":{\"unit\":\"px\",\"size\":27,\"sizes\":[]},\"gap\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"text_color\":\"#2C85EB\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Yeseva One\",\"typography_font_size\":{\"unit\":\"px\",\"size\":36,\"sizes\":[]},\"typography_font_weight\":\"400\",\"typography_font_style\":\"normal\",\"text_spacing\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"_transform_rotateZ_effect_hover\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"_transform_rotate_3d_hover\":\"yes\",\"_transform_rotateX_effect_hover\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"_transform_rotateY_effect_hover\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"_transform_perspective_effect_hover\":{\"unit\":\"px\",\"size\":200,\"sizes\":[]},\"_transform_scale_effect_hover\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]},\"_transform_transition_hover\":{\"unit\":\"px\",\"size\":400,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"divider\"},{\"id\":\"19bb07f\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Futurionix is \\u200b\\u200bdeveloping revolutionary cybernetic technologies that combine biology and synthetics. Their innovations include adaptive implants that can evolve and improve over time.<\\/p>\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Sarpanch\",\"typography_font_size\":{\"unit\":\"px\",\"size\":21,\"sizes\":[]},\"typography_font_weight\":\"400\",\"text_color\":\"#C3A7EB\",\"link_hover_color_transition_duration\":{\"unit\":\"s\",\"size\":1.4,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false},{\