lassName\":\"is-style-button-hover-secondary-bgcolor\",\"style\":{\"border\":{\"radius\":\"60px\"},\"spacing\":{\"padding\":{\"left\":\"34px\",\"right\":\"34px\",\"top\":\"20px\",\"bottom\":\"20px\"}},\"color\":{\"background\":\"#0ec97f36\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|primary\"}}}},\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-button-hover-secondary-bgcolor has-medium-font-size\"><a class=\"wp-block-button__link has-primary-color has-text-color has-background has-link-color wp-element-button\" style=\"border-radius:60px;background-color:#0ec97f36;padding-top:20px;padding-right:34px;padding-bottom:20px;padding-left:34px\">Schedule Demo</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"saaslauncher\",\"area\":\"footer\"} /-->', 'Front Page', 'Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'inherit', 'closed', 'closed', '', '59-revision-v1', '', '', '2025-04-04 11:30:56', '2025-04-04 11:30:56', '', 59, 'http://localhost/futurionix/?p=111', 0, 'revision', '', 0);
