"hasZIndex\":false,\"zIndex\":-10,\"boxShadow\":{\"enabled\":false,\"color\":\"#000\",\"horizontal\":0,\"vertical\":0,\"blur\":10,\"spread\":0,\"position\":\"\"},\"boxShadowHover\":{\"enabled\":false,\"color\":\"#000\",\"horizontal\":0,\"vertical\":0,\"blur\":10,\"spread\":0,\"position\":\"\"},\"transformEnabled\":false,\"transform\":{\"translateX\":0,\"translateY\":0,\"rotate\":0,\"scale\":1},\"transformDefaultEnabled\":false,\"transformDefault\":{\"translateX\":0,\"translateY\":0,\"rotate\":0,\"scale\":1}},\"cozyCustomFont\":\"Metrophobic\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-fill has-big-font-size\"><a class=\"wp-block-button__link has-gradient-twelve-gradient-background has-background wp-element-button\" style=\"border-radius:60px;padding-top:20px;padding-right:34px;padding-bottom:20px;padding-left:34px\"><strong>Explore Our Cybernetic Upgrades</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"40px\",\"bottom\":\"60px\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"},\"cozyAnimation\":{\"type\":\"zoom-in\",\"easingFunction\":\"ease-in\",\"anchorPlacement\":\"top-bottom\",\"duration\":600}} -->\n<div class=\"wp-block-group\" style=\"margin-top:40px;margin-bottom:60px\"><!-- wp:image {\"id\":11631,\"width\":\"142px\",\"height\":\"45px\",\"scale\":\"contain\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://localhost/futurionix/wp-content/themes/saaslauncher/assets/images/users_face.png\" alt=\"\" class=\"wp-image-11631\" style=\"object-fit:contain;width:142px;height:45px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|light-color\"}}}},\"textColor\":\"light-color\"} -->\n<p class=\"has-light-color-color has-text-color has-link-color\">Join 20,000+ Happy User