-column\"><!-- wp:group {\"className\":\"saaslauncher-hover-box\",\"style\":{\"border\":{\"radius\":\"12px\",\"width\":\"0px\",\"style\":\"none\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"dark-shade\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group saaslauncher-hover-box has-dark-shade-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:12px;margin-top:0;margin-bottom:0;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":81,\"width\":\"auto\",\"height\":\"60px\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"50px\"}}} -->\n<figure class=\"wp-block-image size-full is-resized has-custom-border\"><img src=\"http://localhost/futurionix/wp-content/uploads/2025/04/cyber.jpg\" alt=\"\" class=\"wp-image-81\" style=\"border-radius:50px;aspect-ratio:1;object-fit:cover;width:auto;height:60px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":5,\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|light-color\"}}}},\"textColor\":\"light-color\",\"fontSize\":\"medium\"} -->\n<h5 class=\"wp-block-heading has-light-color-color has-text-color has-link-color has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Dr. Nova Synapse</h5>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|foreground-alt\"}}}},\"textColor\":\"foreground-alt\",\"fontSize\":\"small\"} -->\n<p class=\"has-foreground-alt-color has-text-color has-link-color has-small-font-size\">Neuro-AI Specialist &amp; Human Augmentation Advocate</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|foreground-alt\"}}}},\"textColor\":\"foreground-alt\"} -->\n<p class=\"has-foreground-alt-color has-text-color has-link-color\">The neural link in Futurionix’s Cybernetic Eye is revolutionary! It processes visual data 300% faster than the human brain and even integrates with my AI assistant. I can now decode ancient texts in seconds and even detect micro-expressions in negotiations!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":12146,\"width\":\"128px\",\"height\":\"24px\",\"scale\":\"contain\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://localhost/futurionix/wp-content/themes/saaslauncher/assets/images/rating_star.png\" alt=\"\" class=\"wp-image-12146\" style=\"object-fit:contain;width:128px;height:24px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"saaslauncher-hover-box\",\"style\":{\"border\":{\"radius\":\"12px\",\"width\":\"0px\",\"style\":\"none\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"dark-shade\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group saaslauncher-hover-box has-dark-shade-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:12px;margin-top:0;margin-bottom:0;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":82,\"width\":\"auto\",\"height\":\"60px\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"50px\"}}} -->\n<figure class=\"wp-block-image size-full is-resized has-custom-border\"><img src=\"http://localhost/futurionix/wp-content/uploads/2025/04/helix.jpg\" alt=\"\" class=\"wp-image-82\" style=\"border-radius:50px;aspect-ratio:1;object-fit:cover;width:auto;height:60px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":5,\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|light-color\"}}}},\"textColor\":\"light-color\",\"fontSize\":\"medium\"} -->\n<h5 class=\"wp-block-heading has-light-color-color has-text-color has-link-color has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Captain Helix</h5>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|foreground-alt\"}}}},\"textColor\":\"foreground-alt\",\"fontSize\":\"small\"} -->\n<p class=\"has-foreground-alt-color has-text-color has-link-color has-small-font-size\">Ex-Interstellar Smuggler Turned Cybernetic Enthusiast</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|foreground-alt\"}}}},\"textColor\":\"foreground-alt\"} -->\n<p class=\"has-foreground-alt-color has-text-color has-link-color\">Trust me, when you’re smuggling rare artifacts through a black hole, you need the best gear. Futurionix’s cybernetic legs saved me—adaptive shock absorbers, built-in boosters, and zero-gravity stabilization. I can outrun security drones AND gravity itself!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":12146,\"width\":\"128px\",\"height\":\"24px\",\"scale\":\"contain\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://localhost/futurionix/wp-content/themes/saaslauncher/assets/images/rating_star.png\" alt=\"\" class=\"wp-image-12146\" style=\"object-fit:contain;width:128px;height:24px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"saaslauncher-hover-box\",\"style\":{\"border\":{\"radius\":\"12px\",\"width\":\"0px\",\"style\":\"none\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"dark-shade\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group saaslauncher-hover-box has-dark-shade-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:12px;margin-top:0;margin-bottom:0;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":83,\"width\":\"auto\",\"height\":\"60px\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"50px\"}}} -->\n<figure class=\"wp-block-image size-full is-resized has-custom-border\"><img src=\"http://localhost/futurionix/wp-content/uploads/2025/04/zen.jpg\" alt=\"\" class=\"wp-image-83\" style=\"border-radius:50px;aspect-ratio:1;object-fit:cover;width:auto;height:60px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":5,\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|light-color\"}}}},\"textColor\":\"light-color\",\"fontSize\":\"medium\"} -->\n<h5 class=\"wp-block-heading has-light-color-color has-text-color has-link-color has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Zenith-42</h5>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|foreground-alt\"}}}},\"textColor\":\"foreground-alt\",\"fontSize\":\"small\"} -->\n<p class=\"has-foreground-alt-color has-text-color has-link-color has-small-font-size\">AI Consciousness in a Human Body wandering around</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|foreground-alt\"}}}},\"textColor\":\"foreground-alt\"} -->\n<p class=\"has-foreground-alt-color has-text-color has-link-color\">I was born as pure data, but with Futurionix’s cybernetic body, I have finally experienced what it means to be human. Every limb moves with precision, my artificial heartbeat syncs with real emotions, and for the first time—I feel alive. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":12146,\"width\":\"128px\",\"height\":\"24px\",\"scale\":\"contain\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://localhost/futurionix/wp-content/themes/saaslauncher/assets/images/rating_star.png\" alt=\"\" class=\"wp-image-12146\" style=\"object-fit:contain;width:128px;height:24px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"is-style-saaslauncher-overflow-hidden\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"7rem\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"var:preset|spacing|40\"}},\"gradient\":\"gradient-twentyfour\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"860px\"},\"cozyCustomFont\":\"Nixie One\"} -->\n<div class=\"wp-block-group is-style-saaslauncher-overflow-hidden has-gradient-twentyfour-gradient-background has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-right:var(--wp--preset--spacing--40);padding-bottom:7rem;padding-left:var(--wp--preset--spacing--40)\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"64px\"}},\"position\":{\"type\":\"\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"760px\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:64px;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"8px\",\"bottom\":\"8px\",\"left\":\"24px\",\"right\":\"24px\"}},\"border\":{\"radius\":\"60px\",\"width\":\"1px\"}},\"borderColor\":\"border-color\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group is-style-default has-border-color has-border-color-border-color\" style=\"border-width:1px;border-radius:60px;padding-top:8px;padding-right:24px;padding-bottom:8px;padding-left:24px\"><!-- wp:heading {\"level\":5,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|light-color\"}}},\"typography\":{\"textTransform\":\"uppercase\"}},\"textColor\":\"light-color\",\"fontSize\":\"small\"} -->\n<h5 class=\"wp-block-heading has-light-color-color has-text-color has-link-color has-small-font-size\" style=\"text-transform:uppercase\">FAQ</h5>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"cozyCustomFont\":\"Nixie One\"} -->\n<h1 class=\"wp-block-heading has-text-align-center\"><strong>Food - for your curiosity</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|foreground-alt\"}}}},\"textColor\":\"foreground-alt\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-foreground-alt-color has-text-color has-link-color has-medium-font-size\">At <strong>Futurionix</strong>, we don’t just create cybernetic enhancements—we revolutionize the way humans interact with technology and we want to make sure that their concerns are addressed properly. Our mission is to <strong>push the limits of human potential</strong> through cutting-edge biomechanical upgrades that are designed for <strong>performance, precision, and personalization</strong>. Whether you\'re looking to enhance strength, improve vision, or optimize endurance, <strong>Futurionix is your gateway to the future</strong>.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:cozy-block/slider {\"blockClientId\":\"972ff522-1895-454f-95c9-b1fc82449131\",\"thumbMedia\":[\"\",\"\",\"\",\"\",\"\"],\"style\":{\"border\":{\"radius\":\"49px\"}},\"gradient\":\"gradient-twentyfour\"} -->\n<div class=\"wp-block-cozy-block-slider has-gradient-twentyfour-gradient-background has-background\" style=\"border-radius:49px\"><div class=\"cozy-block-slider swiper-container hover-show \" id=\"cozyBlock_972ff522_1895_454f_95c9_b1fc82449131\"><div class=\"swiper-wrapper\"><!-- wp:cozy-block/slide {\"blockClientId\":\"494d862e-0f3f-4508-a5bc-6c2ec67a5210\"} -->\n<!-- wp:cover {\"dimRatio\":50} -->\n<div class=\"wp-block-cover\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slide Title\",\"cozyCustomFont\":\"Nixie One\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">What makes Futurionix implants different from standard medical devices?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Lorem Ipsum is simply dummy text of the printing and typesetting industry.\"} -->\n<p class=\"has-text-align-center\"><strong>Futurionix </strong>implants aren’t just for restoring lost functions — they enhance and evolve the human body. We integrate AI, adaptive synthetic materials, and neural interfaces for seamless connection between mind and machine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\"></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n<!-- /wp:cozy-block/slide -->\n\n<!-- wp:cozy-block/slide {\"blockClientId\":\"23b88836-c775-40ce-92c3-da36cf393a4b\"} -->\n<!-- wp:cover {\"dimRatio\":50} -->\n<div class=\"wp-block-cover\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slide Title\",\"cozyCustomFont\":\"Nixie One\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Are cybernetic enhancements safe?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Lorem Ipsum is simply dummy text of the printing and typesetting industry.\"} -->\n<p class=\"has-text-align-center\"><strong>Yes</strong>. All Futurionix implants are tested under extreme conditions and protected by advanced encryption, anti-tamper systems, and biometric security to prevent unauthorized access or cyberattacks.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\"></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n<!-- /wp:cozy-block/slide -->\n\n<!-- wp:cozy-block/slide {\"blockClientId\":\"6779ec72-a2de-4719-9614-aeacafed6392\"} -->\n<!-- wp:cover {\"dimRatio\":50} -->\n<div class=\"wp-block-cover\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slide Title\",\"cozyCustomFont\":\"Nixie One\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Can the implants evolve or upgrade over time?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Lorem Ipsum is simply dummy text of the printing and typesetting industry.\"} -->\n<p class=\"has-text-align-center\"><strong>Absolutely</strong>. Our bio-synthetic systems support self-optimization, allowing upgrades, regeneration, and performance tuning as your needs change — just like software, but for your body.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\"></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n<!-- /wp:cozy-block/slide -->\n\n<!-- wp:cozy-block/slide {\"blockClientId\":\"dbd0df00-5906-4830-9d4e-2a43ac2b1f67\"} -->\n<!-- wp:cover {\"dimRatio\":50} -->\n<div class=\"wp-block-cover\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slide Title\",\"cozyCustomFont\":\"Nixie One\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Is surgery required for implantation?</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Lorem Ipsum is simply dummy text of the printing and typesetting industry.\"} -->\n<p class=\"has-text-align-center\">Most devices are installed using minimally invasive techniques. Some next-gen implants are even deployed via nanobots, enabling painless and fast integration with minimal downtime.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\"></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n<!-- /wp:cozy-block/slide -->\n\n<!-- wp:cozy-block/slide {\"blockClientId\":\"6d3f235a-6312-4942-a8ee-4ff05ebda0c7\"} -->\n<!-- wp:cover {\"dimRatio\":50} -->\n<div class=\"wp-block-cover\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slide Title\",\"cozyCustomFont\":\"Nixie One\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Can I customize my enhancements?</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Lorem Ipsum is simply dummy text of the printing and typesetting industry.\"} -->\n<p class=\"has-text-align-center\"><strong>Yes</strong>. From function and performance to aesthetic appearance, every implant can be tailored to your identity. You don’t just wear technology — you become it.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\"></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n<!-- /wp:cozy-block/slide --></div><div class=\"swiper-button-prev cozy-block-button-prev\"></div><div class=\"swiper-button-next cozy-block-button-next\"></div><div class=\"swiper-pagination cozy-pagination\"></div></div></div>\n<!-- /wp:cozy-block/slider --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:button {\"backgroundColor\":\"tertiary\",\"textColor\":\"foregound-alt\",\"className\":\"saaslauncher-scrollto-top is-style-button-hover-secondary-bgcolor\",\"style\":{\"border\":{\"radius\":\"50%\"}}} -->\n<div class=\"wp-block-button saaslauncher-scrollto-top is-style-button-hover-secondary-bgcolor\"><a class=\"wp-block-button__link has-foregound-alt-color has-tertiary-background-color has-text-color has-background wp-element-button\" style=\"border-radius:50%\">Scroll to Top</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"saaslauncher\",\"area\":\"footer\"} /-->', 'Front Page', 'Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'inherit', 'closed', 'closed', '', '59-revision-v1', '', '', '2025-04-04 18:34:50', '2025-04-04 18:34:50', '', 59, 'http://localhost/futurionix/?p=174', 0, 'revision', '', 0);
