} -->\n<h4 class=\"wp-block-heading has-light-color-color has-text-color has-link-color has-big-font-size\" style=\"font-style:normal;font-weight:500\">Search</h4>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:search {\"label\":\"Search\",\"showLabel\":false,\"placeholder\":\"Search...\",\"buttonText\":\"Search\",\"buttonPosition\":\"button-inside\",\"buttonUseIcon\":true,\"style\":{\"border\":{\"radius\":\"8px\",\"width\":\"0px\",\"style\":\"none\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}},\"backgroundColor\":\"primary\",\"textColor\":\"light-color\",\"fontSize\":\"small\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"28px\",\"right\":\"28px\"}},\"border\":{\"width\":\"1px\",\"color\":\"#292929\",\"radius\":\"12px\"}},\"backgroundColor\":\"dark-shade\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"100%\"}} -->\n<div class=\"wp-block-group has-border-color has-dark-shade-background-color has-background\" style=\"border-color:#292929;border-width:1px;border-radius:12px;padding-top:40px;padding-right:28px;padding-bottom:40px;padding-left:28px\"><!-- wp:image {\"id\":12,\"width\":\"138px\",\"height\":\"auto\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"radius\":\"100px\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized has-custom-border\" style=\"margin-top:0;margin-bottom:0\"><img src=\"http://localhost/futurionix/wp-content/uploads/2025/04/cyber_theme_logo_with_the_name_Futurionix_5_-removebg-preview.png\" alt=\"\" class=\"wp-image-12\" style=\"border-radius:100px;aspect-ratio:1;object-fit:cover;width:138px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vivid-purple\"}}},\"spacing\":{\"margin\":{\"top\":\"40px\"}}},\"textColor\":\"vivid-purple\",\"fontSize\":\"x-large\",\"cozyCustomFont\":\"Strait\"} -->\n<h4 class=\"wp-block-heading has-text-align-center has-vivid-purple-color has-text-color has-link-color has-x-large-font-size\" style=\"margin-top:40px\">Futurionix</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#07c5e3\"}}},\"spacing\":{\"margin\":{\"top\":\"10px\",\"bottom\":\"0\"}},\"color\":{\"text\":\"#07c5e3\"}}} -->\n<p class=\"has-text-align-center has-text-color has-link-color\" style=\"color:#07c5e3;margin-top:10px;margin-bottom:0\">Whether you\'re seeking cutting-edge prosthetics, want to enhance your physical or mental performance, or explore the potential of AI interfaces, <strong>Futurionix is your partner in evolution.</strong> We\'re not just about creating products; we’re about creating a community of empowered individuals ready to embrace a limitless future.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:social-links {\"iconColor\":\"light-color\",\"iconColorValue\":\"#FFFFFE\",\"size\":\"has-normal-icon-size\",\"align\":\"center\",\"className\":\"is-style-logos-only\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\",\"left\":\"var:preset|spacing|40\"},\"margin\":{\"bottom\":\"0\"}}}} -->\n<ul class=\"wp-block-social-links aligncenter has-normal-icon-size has-icon-color is-style-logos-only\" style=\"margin-bottom:0\"><!-- wp:social-link {\"url\":\"https://www.instagram.com/cyberpunkgame/\",\"service\":\"instagram\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.facebook.com/CyberpunkGame\",\"service\":\"facebook\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.linkedin.com/company/cd-projekt-red\",\"service\":\"linkedin\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://x.com/cdprojektred?lang=en\",\"service\":\"x\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.youtube.com/@CyberpunkGame\",\"service\":\"youtube\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.cyberpunkgame.tumblr.com/\",\"service\":\"tumblr\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.twitch.tv/cdprojektred\",\"service\":\"twitch\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"28px\",\"bottom\":\"28px\",\"left\":\"28px\",\"right\":\"28px\"}},\"border\":{\"width\":\"1px\",\"color\":\"#292929\",\"radius\":\"12px\"}},\"backgroundColor\":\"dark-shade\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"100%\"}} -->\n<div class=\"wp-block-group has-border-color has-dark-shade-background-color has-background\" style=\"border-color:#292929;border-width:1px;border-radius:12px;padding-top:28px;padding-right:28px;padding-bottom:28px;padding-left:28px\"><!-- wp:heading {\"textAlign\":\"left\",\"level\":4,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|light-color\"}}},\"spacing\":{\"margin\":{\"top\":\"0px\"}}},\"textColor\":\"light-color\",\"fontSize\":\"big\"} -->\n<h4 class=\"wp-block-heading has-text-align-left has-light-color-color has-text-color has-link-color has-big-font-size\" style=\"margin-top:0px\"><strong>Join the Future – Subscribe to Our Newsletter</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|foreground-alt\"}}},\"spacing\":{\"margin\":{\"top\":\"10px\",\"bottom\":\"var:preset|spacing|20\"}}},\"textColor\":\"foreground-alt\"} -->\n<p class=\"has-text-align-left has-foreground-alt-color has-text-color has-link-color\" style=\"margin-top:10px;margin-bottom:var(--wp--preset--spacing--20)\">Stay connected with the latest in cybernetic innovations, exclusive upgrades, and next-gen tech. Get updates directly from the edge of human evolution.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"level\":5,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|light-color\"}}},\"spacing\":{\"margin\":{\"top\":\"0px\"}}},\"textColor\":\"light-color\",\"fontSize\":\"normal\"} -->\n<h5 class=\"wp-block-heading has-text-align-left has-light-color-color has-text-color has-link-color has-normal-font-size\" style=\"margin-top:0px\"><a href=\"http://localhost/futurionix/newsletter/\" data-type=\"page\" data-id=\"308\"><strong>Subscribe for early access to product drops, insider insights, and limited offers</strong> here</a></h5>\n<!-- /wp:heading -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p>No spam. Just pure innovation.</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|60\"},\"padding\":{\"top\":\"28px\",\"bottom\":\"5px\",\"left\":\"28px\",\"right\":\"28px\"}},\"border\":{\"radius\":\"12px\",\"width\":\"1px\",\"color\":\"#292929\"}},\"backgroundColor\":\"dark-shade\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-border-color has-dark-shade-background-color has-background\" style=\"border-color:#292929;border-width:1px;border-radius:12px;margin-bottom:var(--wp--preset--spacing--60);padding-top:28px;padding-right:28px;padding-bottom:5px;padding-left:28px\"><!-- wp:group {\"style\":{\"border\":{\"bottom\":{\"color\":\"var:preset|color|border-color\",\"width\":\"1px\"},\"top\":[],\"right\":[],\"left\":[]},\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\"},\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"border-bottom-color:var(--wp--preset--color--border-color);border-bottom-width:1px;margin-bottom:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|light-color\"}}}},\"textColor\":\"light-color\",\"fontSize\":\"big\"} -->\n<h4 class=\"wp-block-heading has-light-color-color has-text-color has-link-color has-big-font-size\" style=\"font-style:normal;font-weight:500\">Latest Posts</h4>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}},\"border\":{\"width\":\"0px\",\"style\":\"none\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1180px\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\" style=\"border-style:none;border-width:0px;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:query {\"queryId\":29,\"query\":{\"perPage\":4,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"exclude\",\"inherit\":false}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template {\"layout\":{\"type\":\"default\",\"columnCount\":3}} -->\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"16px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"100px\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:100px\"><!-- wp:post-featured-image {\"isLink\":true,\"width\":\"100px\",\"height\":\"90px\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}}} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\" sty